import sys
import math

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        ops = []

        if n == 3:
            ops.append((3, 2))
            ops.append((3, 2))
        else:
            x = n
            while x > 1:
                y = int(math.sqrt(x))
                if y < 2:
                    y = 2
                if x == y:
                    y = 2
                if y == x:
                    y = 2
                if x // y + (1 if x % y else 0) == x:
                    y = 2
                ops.append((x, y))
                x = math.ceil(x / y)

            for i in range(3, n + 1):
                ops.append((i, n))

            while n > 1:
                ops.append((n, 2))
                n = math.ceil(n / 2)

        results.append(str(len(ops)))
        for x, y in ops:
            results.append(f"{x} {y}")

    print("\n".join(results))

if __name__ == "__main__":
    solve()
